from typing import List

def max_score(grid: List[List[int]]) -> int:
    n, m = len(grid), len(grid[0])
    dp = [[0] * m for _ in range(n)]
    dp_prev = [[0] * m for _ in range(n)]
    unique_values = set()

    for i in range(n):
        for j in range(m):
            dp[i][j] = grid[i][j]
            unique_values.add(grid[i][j])
            dp_prev[i][j] = grid[i][j]
            if i > 0:
                dp[i][j] = max(dp[i][j], dp_prev[i-1][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp_prev[i][j-1])

    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            for k in range(i+1, n):
                if grid[k][j] not in unique_values:
                    dp[i][j] = max(dp[i][j], dp[k][j] + dp_prev[i][j])
            for l in range(j+1, m):
                if grid[i][l] not in unique_values:
                    dp[i][j] = max(dp[i][j], dp[i][l] + dp_prev[i][j])

    return dp[0][0]

